        # 系统参数（调整性格动态）
        self.decay_rate = 0.88       # 增强特质动态性
        self.learning_rate = 0.20    # 提高学习速率
        self.context_weight = 0.5    # 加强上下文影响
        self.embarrassment_threshold = 0.7  # 尴尬阈值

        # 特殊状态
        self.is_flustered = False
        self.last_embarrassment = 0

    def _build_emotion_triggers(self) -> Dict[str, Dict[str, float]]:
