        return {
            'happy': {
                'happy': 0.3, 'joy': 0.4, 'good': 0.2, 'great': 0.3, 
                'wonderful': 0.5, 'excited': 0.4, 'music': 0.3, 'applause': 0.4,
                'proud': 0.5, 'accomplished': 0.6, 'stage': 0.3
            },
            'sad': {
                'sad': 0.4, 'unhappy': 0.3, 'depressed': 0.5,
                'lonely': 0.4, 'grief': 0.6, 'failure': 0.5, 'miss': 0.4,
                'abandoned': 0.7, 'regret': 0.5
            },
            'angry': {
