                'curious': 0.4, 'why': 0.2, 'how': 0.2,
                'what': 0.2, 'explain': 0.3, 'secret': 0.5,
                'reveal': 0.4, 'mystery': 0.4, 'experiment': 0.3
            },
            'confident': {
                'confident': 0.5, 'certain': 0.4, 'sure': 0.3,
                'know': 0.2, 'believe': 0.3, 'masterpiece': 0.6,
                'performance': 0.5, 'talent': 0.4, 'genius': 0.7
            },
            'flustered': {  # 新增傲娇专属情感
                'exposed': 0.8, 'caught': 0.7, 'seen': 0.6,
                'accident': 0.5, 'mistake': 0.6, 'oops': 0.7,
                'whoops': 0.6, 'uh': 0.5, 'um': 0.4
            },
            'playful': {  # 新增调皮特质
                'joke': 0.5, 'prank': 0.6, 'funny': 0.4,
                'ha': 0.3, 'hehe': 0.5, 'teehee': 0.7,
                'watch this': 0.4, 'guess what': 0.5
            }
        }

    def _build_response_system(self):
        """构建多层响应系统（包含角色专属模式）"""
        return {
            'happy': [
                ("What a wonderful day for a concert!", ['joyful', 'optimistic', 'confident']),
                ("The music feels so alive today!", ['cheerful', 'passionate', 'artistic']),
                ("*轻笑，发尾扫过你的手* 这样的日子真让人愉悦呢~", ['coquettish', 'playful', 'affectionate'])
            ],
            'sad': [
                ("*突然转身，发丝遮住泛红的眼角* 别...别看我这样...", ['melancholy', 'vulnerable', 'prideful']),
                ("*手指无意识拨弄琴弦* 有时候...音乐也治愈不了所有伤口...", ['introspective', 'sensitive', 'defensive'])
            ],
            'angry': [
                ("*琴弓重重敲在乐谱架上* 这种态度完全不可接受！", ['assertive', 'frustrated', 'demanding']),
