        if "seen" in text or "watched" in text:
            scores["flustered"] += min(0.5 + self.trait_values["flustered"]*0.3, 1.0)

        if "joke" in text or "fun" in text:
            scores["playful"] += min(0.4 + self.trait_values["playful"]*0.2, 0.8)

        # 情感强度增强（角色特质影响）
        max_score = max(scores.values(), default=0)
        if max_score > 0:
            for emo in scores:
                base_boost = 1.0
                if emo == "flustered" and self.is_flustered:
                    base_boost = 1.5
                elif emo == "playful" and self.trait_values["playful"] > 0.6:
                    base_boost = 1.3
                scores[emo] = (scores[emo] / max_score) ** 1.3 * base_boost

