            if trait in emotion_scores:
                delta = emotion_scores[trait] * self.learning_rate
                if feedback == 'positive':
                    delta *= 1.6 if trait == "happy" else 1.3
                elif feedback == 'negative':
                    delta *= 0.5 if trait == "angry" else 0.7
                self.trait_values[trait] += delta

                # 傲娇反向强化
                if self.is_flustered and trait == "flustered":
                    delta *= 1.8
                elif self.is_flustered and trait == "confident":
                    delta *= 0.5

        # 上下文影响（增强）
        if self.conversation_history:
            context_traits = [t for _, traits in self.conversation_history[-self.context_window:] for t in traits]
            for trait in set(context_traits):
                context_boost = self.context_weight * context_traits.count(trait)
                if trait == "playful" and self.trait_values["playful"] > 0.5:
                    context_boost *= 1.3
                self.trait_values[trait] += context_boost

        # 情感记忆更新
        for emo, score in emotion_scores.items():
            self.emotional_memory[emo] = max(self.emotional_memory[emo], score * 0.8)

        self._normalize_weights()
        self.conversation_history.append((user_input, list(emotion_scores.keys())))  # 更新历史

    def generate_response(self) -> str:
        """增强响应生成（包含角色专属逻辑）"""
        # 计算当前特质状态
        active_traits = sorted(
            self.trait_weights.items(),
            key=lambda x: x[1],
            reverse=True
        )[:4]  # 增加考虑的特质数量

        # 构建响应候选池
        candidate_responses = []
        for trait, weight in active_traits:
            if trait in self.response_db:
                for resp_data in self.response_db[trait]:
                    if isinstance(resp_data, tuple):
                        resp, resp_traits = resp_data
                        bonus = 1.0
                        if self.is_flustered and "flustered" in resp_traits:
                            bonus = 1.5
                        if "playful" in resp_traits and self.trait_values["playful"] > 0.6:
                            bonus = 1.3
                        candidate_responses.append(
                            (resp, resp_traits, weight * (1 + 0.4*len(resp_traits)) * bonus)
                        )
                    else:
                        # 处理可能的单元素响应
                        resp = resp_data
                        candidate_responses.append((resp, [trait], weight))

        # 角色专属逻辑：避免重复响应
        recent_responses = self.response_history[-3:] if len(self.response_history) >=3 else self.response_history
        candidate_responses = [
            (resp, traits, weight) for resp, traits, weight in candidate_responses
            if resp not in recent_responses or random.random() < 0.3
        ]

        # 加权随机选择
        if not candidate_responses:
            return "I'm not sure what to say right now."

        total_weight = sum(w for _, _, w in candidate_responses)
        rand_val = random.uniform(0, total_weight)
        cumulative = 0
        selected = None

        for resp, traits, weight in candidate_responses:
            cumulative += weight
            if rand_val <= cumulative:
                selected = (resp, traits)
                break

        if selected:
            self.last_used_traits = selected[1]
            self.response_history.append(selected[0])
            # 傲娇状态重置逻辑
            if self.is_flustered and "flustered" in selected[1]:
                self.is_flustered = False if random.random() < 0.7 else True
            return selected[0]

        return "I'm not sure what to say right now."

    def process_feedback(self, feedback_type: str):
        """增强反馈处理（包含角色专属机制）"""
        feedback_strength = {
            'positive': 1.7,
            'negative': 0.5,
            'neutral': 1.0
        }.get(feedback_type, 1.0)

        # 增强/减弱最近使用的特质
        for trait in self.last_used_traits:
            if trait in self.trait_values:
                if trait == "flustered" and feedback_type == "negative":
                    self.trait_values[trait] *= 0.6
                else:
                    self.trait_values[trait] *= feedback_strength

        # 傲娇强化逻辑
        if feedback_type == "positive" and "flustered" in self.last_used_traits:
            self.trait_values["confident"] *= 1.2

        self._normalize_weights()

    def long_term_development(self):
        """增强长期性格发展（包含角色专属路径）"""
        # 基础性格回归趋势
        for trait, base_val in self.base_traits.items():
            current = self.trait_values[trait]
            regression_factor = 0.07 if trait in ["confident", "playful"] else 0.05
            self.trait_values[trait] += (base_val - current) * regression_factor

        # 经验积累效果
        historical_traits = [t for _, traits in self.conversation_history for t in traits]
        for trait in set(historical_traits):
            count = historical_traits.count(trait)
            if count > 5:
                boost = 1 + (count * 0.015)
                if trait == "playful":
                    boost *= 1.2  # 调皮特质更容易强化
                self.trait_values[trait] *= boost

        # 傲娇状态长期影响
        if self.emotional_memory["flustered"] > 0.6:
            self.trait_values["confident"] *= 0.95
            self.trait_values["flustered"] *= 1.1

        self._normalize_weights()

