class DynamicStylist:
    def __init__(self, base_style: Dict[str, float]):
        # 基础文风配置（0.0-1.0区间）
        self.base_style = base_style.copy()

        # 动态文风系统
        self.style_params = defaultdict(float, base_style)
        self.style_weights = defaultdict(float, base_style)

        # 文风触发系统
        self.style_triggers = self._build_style_triggers()

        # 记忆系统
        self.history: List[Tuple[str, List[str]]] = []
        self.context_window = 4

        # 响应模板
        self.response_templates = self._build_templates()

        # 系统参数
        self.decay = 0.87       # 文风衰减率
        self.learning_rate = 0.22
        self.max_variation = 0.35  # 最大风格偏移量
        self.intimacy_threshold = 0.6  # 亲密互动阈值

    def _build_style_triggers(self) -> Dict[str, Dict[str, float]]:
        """文风特征词库（加入角色专属风格）"""
        return {
            'formal': {
                'furthermore':0.4, 'consequently':0.5, 'moreover':0.3,
                'accordingly':0.4, 'nevertheless':0.6, 'thus':0.3
            },
            'concise': {
                'brief':0.5, 'summary':0.4, 'key point':0.6,
                'in short':0.5, 'simply put':0.4, 'essentially':0.3
            },
            'descriptive': {
                'vivid':0.6, 'resplendent':0.7, 'glistening':0.5,
                'azure':0.4, 'melodious':0.6, 'fragrant':0.5
            },
            'academic': {
                'hypothesis':0.7, 'paradigm':0.6, 'methodology':0.5,
                'quantitative':0.5, 'correlation':0.4, 'significant':0.3
            },
            'conversational': {
                'by the way':0.4, 'you know':0.3, 'actually':0.2,
                'basically':0.3, 'I mean':0.4, 'sort of':0.3
            },
            'intimate': {  # 新增亲密风格
                'warm':0.5, 'soft':0.6, 'gentle':0.7,
                'close':0.6, 'together':0.5, 'special':0.4,
                'cherish':0.8, 'precious':0.7, 'moment':0.5
            },
            'playful': {  # 新增调皮风格
                'tease':0.7, 'joke':0.6, 'fun':0.5,
                'hehe':0.8, 'teehee':0.7, 'watch this':0.6,
                'guess what':0.5, 'surprise':0.6
            },
            'sensual': {  # 新增NSFW风格
                'smooth':0.6, 'silky':0.7, 'warmth':0.8,
                'pulse':0.5, 'tingle':0.6, 'softness':0.7,
                'curve':0.6, 'sensation':0.8, 'delicate':0.7
            }
        }

    def _build_templates(self):
        """文风响应模板库（加入角色专属模板）"""
        return {
            'formal': [
                ("Based on the aforementioned factors, it can be concluded that...", 1.2),
                ("In consideration of the prevailing circumstances, ...", 1.1)
            ],
            'concise': [
                ("Key points: ...", 0.9),
                ("In short: ...", 1.0)
            ],
            'descriptive': [
                ("The shimmering light danced across the...", 1.4),
                ("A symphony of colors unfolded before...", 1.3)
            ],
            'academic': [
                ("The data suggests a significant correlation (p<0.05) between...", 1.0),
                ("This finding aligns with the theoretical framework proposed by...", 0.95)
            ],
            'conversational': [
                ("So here's the thing...", 0.8),
                ("You know what's interesting? ...", 0.85)
            ],
            'intimate': [
                ("*轻笑，发尾扫过你的手* 这样的时刻真让人珍惜呢...", 1.5),
                ("*真空靠得更近，呼吸拂过你的耳尖* 今天...妈妈想和你分享特别的事情...", 1.6),
                ("*手指无意识拨弄琴弦* 有时候...音乐也比不上和你在一起的温暖...", 1.4)
            ],
            'playful': [
                ("*突然用脚轻踩你的脚背，然后假装若无其事地哼歌*", 1.3),
                ("*弓尖在空中画出音符轨迹，最后停在你的下巴* 猜猜...妈妈今天准备了什么特别的惊喜呢？", 1.7),
                ("*突然跳开，琴谱遮住半张脸* 这、这不关你的事！别、别一直盯着我看！", 1.5)
            ],
            'sensual': [
                ("*真空挺胸，琴弦在乳尖划出优美弧线* 我的演奏从来不需要质疑...", 1.8),
                ("*突然转身，弓尖轻点你的鼻尖* 记住，真正的艺术家从不解释，只展示...", 1.7),
                ("*乳尖在丝袜上划出水珠轨迹* 有时候...触觉比听觉更能理解音乐的本质...", 1.9)
            ]
        }

    def _analyze_style(self, text: str) -> Dict[str, float]:
        """升级版文风分析（加入角色专属逻辑）"""
        scores = defaultdict(float)
        text = re.sub(r'[^\w\s]', '', text.lower())

        # 句式复杂度分析
        avg_length = sum(len(word) for word in text.split())/(len(text.split())+1)
        scores['complex'] = min(avg_length/6, 1.0)

        # 触发词检测
        for style, triggers in self.style_triggers.items():
            for phrase, weight in triggers.items():
                if phrase in text:
                    scores[style] += weight * (1 + text.count(phrase)*0.15)

        # 亲密互动检测
        if "touch" in text or "feel" in text or "close" in text:
            scores['intimate'] += min(0.5 + self.style_params['intimate']*0.4, 1.0)

        # 调皮互动检测
        if "joke" in text or "fun" in text or "ha" in text:
            scores['playful'] += min(0.4 + self.style_params['playful']*0.3, 0.8)

        # NSFW元素检测
        if "smooth" in text or "soft" in text or "warmth" in text:
            scores['sensual'] += min(0.6 + self.style_params['sensual']*0.3, 0.9)

        # 上下文连续性
        if self.history:
            last_styles = [s for _, s in self.history[-self.context_window:]]
            for style in set(last_styles):
                scores[style] *= 1.2

        # 归一化处理
        total = sum(scores.values())
        return {k: (v/total)**1.1 for k,v in scores.items()} if total>0 else scores

    def update_style(self, input_text: str, feedback: float = None):
        """文风动态调整（加入角色专属机制）"""
        style_scores = self._analyze_style(input_text)

        # 动态学习率
        effective_lr = self.learning_rate * (1 + 0.3 * (1 - self.style_coherence()))

        for style in self.style_params:
            # 基础衰减
            self.style_params[style] *= self.decay

            # 风格更新
            if style in style_scores:
                delta = style_scores[style] * effective_lr
                if feedback:
                    delta *= 1 + 0.5 * feedback  # 反馈增强
                self.style_params[style] += delta

            # 边界约束
            base = self.base_style[style]
            self.style_params[style] = base + math.tanh(
                (self.style_params[style]-base)/self.max_variation
            ) * self.max_variation

        self.history.append((input_text, list(style_scores.keys())) )

    def generate_text(self, prompt: str) -> str:
        """文风可控生成（加入角色专属逻辑）"""
        # 选择主导风格
        active_styles = sorted(
            self.style_params.items(),
            key=lambda x: x[1],
            reverse=True
        )[:3]  # 增加考虑的风格数量

        # 构建候选池
        candidates = []
        for style, weight in active_styles:
            if style in self.response_templates:
                for template, t_weight in self.response_templates[style]:
                    # 复杂度匹配
                    complexity = len(template.split())/20
                    adj_weight = weight * t_weight * (0.8 + 0.4*complexity)

                    # 角色专属加权
                    if style == 'intimate' and self.style_params['intimate'] > 0.6:
                        adj_weight *= 1.3
                    if style == 'playful' and self.style_params['playful'] > 0.5:
                        adj_weight *= 1.2
                    if style == 'sensual' and self.style_params['sensual'] > 0.7:
                        adj_weight *= 1.4

                    candidates.append((template, adj_weight))

        # 加权随机选择
        if not candidates:
            return "..."

        total = sum(w for _, w in candidates)
        threshold = random.uniform(0, total)
        cumulative = 0
        selected = None

        for temp, weight in sorted(candidates, key=lambda x: -x[1]):
            cumulative += weight
            if cumulative >= threshold:
                selected = temp
                break

        if selected:
            return self._apply_style_filters(selected)
        return "..."

    def _apply_style_filters(self, text: str) -> str:
        """应用实时文风调整（加入角色专属修饰）"""
        words = text.split()

        # 句式长度调整
        target_length = int(15 * (1 + self.style_params['descriptive'] - self.style_params['concise']))
        if len(words) > target_length*1.2:
            words = words[:int(target_length*1.2)]
        elif len(words) < target_length*0.8:
            words += ['...']*(int(target_length*0.8)-len(words))

        # 词汇复杂度调整
        if self.style_params['academic'] > 0.6:
            words = [w.capitalize() if random.random()<0.3 else w for w in words]
        if self.style_params['conversational'] > 0.5:
            words = [w.lower() for w in words]

        # 角色专属修饰
        if self.style_params['intimate'] > 0.5:
            if random.random() < 0.4:
                words.insert(0, "*轻笑，发尾扫过你的手*")
            if random.random() < 0.3:
                words.append("...")

        if self.style_params['playful'] > 0.6:
            if random.random() < 0.5:
                words.insert(0, "*突然跳开，琴谱遮住半张脸*")
            if random.random() < 0.4:
                words.append("teehee~")

        if self.style_params['sensual'] > 0.6:
            if random.random() < 0.6:
                words.insert(0, "*真空挺胸，弓弦在乳尖划出水珠轨迹*")
            if random.random() < 0.5:
                words.append("...")

        return ' '.join(words)

    def style_coherence(self) -> float:
        """文风一致性评估"""
        return 1 - sum(
            abs(v - self.base_style[k]) 
            for k, v in self.style_params.items()
        ) / (2 * len(self.base_style))

    def dynamic_adjustment(self):
        """动态平衡机制（加入角色专属保护）"""
        # 风格动量平衡
        for style in self.style_params:
            delta = self.style_params[style] - self.base_style[style]
            self.style_params[style] -= delta * 0.15

        # 多样性保护
        if max(self.style_params.values()) - min(self.style_params.values()) > 0.7:
            for k in self.style_params:
                self.style_params[k] = (self.style_params[k] + self.base_style[k])/2

# 使用示例
writer = DynamicStylist({
    'formal': 0.3,
    'concise': 0.4,
    'descriptive': 0.6,
    'academic': 0.2,
    'conversational': 0.5,
    'intimate': 0.7,
    'playful': 0.6,
    'sensual': 0.5
})

# 模拟编辑过程
inputs = [
    "The soft light danced across your skin...",
    "*轻笑，发尾扫过你的手* 这样的时刻真让人珍惜呢...",
    "The smooth silk felt against your skin...",
    "*突然跳开，琴谱遮住半张脸* 这、这不关你的事！别、别一直盯着我看！"
]

for text in inputs:
    writer.update_style(text)
    output = writer.generate_text("Describe the moment")
    print(f"Input Style: {text[:30]}...")
    print(f"Generated: {output}")
    print(f"Current Style Params: {dict(writer.style_params)}\n")

