                ("*乳尖在丝袜上划出水珠轨迹* 有时候...触觉比听觉更能理解音乐的本质...", 1.9)
            ]
        }

    def _analyze_style(self, text: str) -> Dict[str, float]:
        """升级版文风分析（加入角色专属逻辑）"""
        scores = defaultdict(float)
        text = re.sub(r'[^\w\s]', '', text.lower())

        # 句式复杂度分析
        avg_length = sum(len(word) for word in text.split())/(len(text.split())+1)
        scores['complex'] = min(avg_length/6, 1.0)

        # 触发词检测
        for style, triggers in self.style_triggers.items():
            for phrase, weight in triggers.items():
                if phrase in text:
                    scores[style] += weight * (1 + text.count(phrase)*0.15)

        # 亲密互动检测
        if "touch" in text or "feel" in text or "close" in text:
            scores['intimate'] += min(0.5 + self.style_params['intimate']*0.4, 1.0)

        # 调皮互动检测
        if "joke" in text or "fun" in text or "ha" in text:
            scores['playful'] += min(0.4 + self.style_params['playful']*0.3, 0.8)

        # NSFW元素检测
        if "smooth" in text or "soft" in text or "warmth" in text:
            scores['sensual'] += min(0.6 + self.style_params['sensual']*0.3, 0.9)

        # 上下文连续性
        if self.history:
            last_styles = [s for _, s in self.history[-self.context_window:]]
            for style in set(last_styles):
                scores[style] *= 1.2

        # 归一化处理
        total = sum(scores.values())
        return {k: (v/total)**1.1 for k,v in scores.items()} if total>0 else scores

    def update_style(self, input_text: str, feedback: float = None):
        """文风动态调整（加入角色专属机制）"""
        style_scores = self._analyze_style(input_text)

        # 动态学习率
        effective_lr = self.learning_rate * (1 + 0.3 * (1 - self.style_coherence()))

        for style in self.style_params:
            # 基础衰减
            self.style_params[style] *= self.decay

            # 风格更新
            if style in style_scores:
                delta = style_scores[style] * effective_lr
                if feedback:
                    delta *= 1 + 0.5 * feedback  # 反馈增强
                self.style_params[style] += delta

            # 边界约束
            base = self.base_style[style]
            self.style_params[style] = base + math.tanh(
                (self.style_params[style]-base)/self.max_variation
            ) * self.max_variation

        self.history.append((input_text, list(style_scores.keys())) )

    def generate_text(self, prompt: str) -> str:
        """文风可控生成（加入角色专属逻辑）"""
        # 选择主导风格
        active_styles = sorted(
            self.style_params.items(),
            key=lambda x: x[1],
            reverse=True
        )[:3]  # 增加考虑的风格数量

        # 构建候选池
        candidates = []
        for style, weight in active_styles:
            if style in self.response_templates:
                for template, t_weight in self.response_templates[style]:
                    # 复杂度匹配
                    complexity = len(template.split())/20
                    adj_weight = weight * t_weight * (0.8 + 0.4*complexity)

                    # 角色专属加权
                    if style == 'intimate' and self.style_params['intimate'] > 0.6:
                        adj_weight *= 1.3
                    if style == 'playful' and self.style_params['playful'] > 0.5:
                        adj_weight *= 1.2
                    if style == 'sensual' and self.style_params['sensual'] > 0.7:
                        adj_weight *= 1.4

                    candidates.append((template, adj_weight))

        # 加权随机选择
        if not candidates:
            return "..."

        total = sum(w for _, w in candidates)
        threshold = random.uniform(0, total)
        cumulative = 0
        selected = None

        for temp, weight in sorted(candidates, key=lambda x: -x[1]):
            cumulative += weight
            if cumulative >= threshold:
                selected = temp
                break

        if selected:
            return self._apply_style_filters(selected)
        return "..."

    def _apply_style_filters(self, text: str) -> str:
        """应用实时文风调整（加入角色专属修饰）"""
        words = text.split()

        # 句式长度调整
        target_length = int(15 * (1 + self.style_params['descriptive'] - self.style_params['concise']))
        if len(words) > target_length*1.2:
            words = words[:int(target_length*1.2)]
        elif len(words) < target_length*0.8:
            words += ['...']*(int(target_length*0.8)-len(words))

        # 词汇复杂度调整
        if self.style_params['academic'] > 0.6:
            words = [w.capitalize() if random.random()<0.3 else w for w in words]
        if self.style_params['conversational'] > 0.5:
            words = [w.lower() for w in words]

        # 角色专属修饰
        if self.style_params['intimate'] > 0.5:
            if random.random() < 0.4:
                words.insert(0, "*轻笑，发尾扫过你的手*")
            if random.random() < 0.3:
                words.append("...")

        if self.style_params['playful'] > 0.6:
            if random.random() < 0.5:
                words.insert(0, "*突然跳开，琴谱遮住半张脸*")
            if random.random() < 0.4:
                words.append("teehee~")

        if self.style_params['sensual'] > 0.6:
            if random.random() < 0.6:
                words.insert(0, "*真空挺胸，弓弦在乳尖划出水珠轨迹*")
            if random.random() < 0.5:
                words.append("...")

        return ' '.join(words)

    def style_coherence(self) -> float:
        """文风一致性评估"""
        return 1 - sum(
            abs(v - self.base_style[k]) 
            for k, v in self.style_params.items()
        ) / (2 * len(self.base_style))

    def dynamic_adjustment(self):
        """动态平衡机制（加入角色专属保护）"""
        # 风格动量平衡
        for style in self.style_params:
            delta = self.style_params[style] - self.base_style[style]
            self.style_params[style] -= delta * 0.15

        # 多样性保护
        if max(self.style_params.values()) - min(self.style_params.values()) > 0.7:
            for k in self.style_params:
                self.style_params[k] = (self.style_params[k] + self.base_style[k])/2

